-- ----------------------------
-- Table structure for gf_member
-- ----------------------------
DROP TABLE IF EXISTS `gf_member`;
CREATE TABLE IF NOT EXISTS `gf_member` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT,
  `business_id` int(11) NOT NULL DEFAULT 1,
  `username` varchar(32) COLLATE NOCASE NULL DEFAULT '',
  `name` varchar(50) COLLATE NOCASE NOT NULL DEFAULT '',
  `nickname` varchar(50) COLLATE NOCASE NULL DEFAULT '',
  `remark` varchar(255) COLLATE NOCASE NOT NULL DEFAULT '',
  `password` varchar(32) COLLATE NOCASE NULL DEFAULT '',
  `salt` varchar(30) COLLATE NOCASE NULL DEFAULT '',
  `email` varchar(100) COLLATE NOCASE NULL DEFAULT '',
  `mobile` varchar(11) COLLATE NOCASE NULL DEFAULT '',
  `avatar` varchar(255) COLLATE NOCASE NULL DEFAULT '',
  `level` tinyint(3) NOT NULL DEFAULT 0,
  `sex` tinyint(3) NOT NULL DEFAULT 0,
  `birthday` date NULL DEFAULT NULL,
  `money` decimal(10, 2) NOT NULL DEFAULT 0,
  `score` int(11) NOT NULL DEFAULT 0,
  `successions` int(10) NOT NULL DEFAULT 1,
  `maxsuccessions` int(10) NOT NULL DEFAULT 1,
  `prevtime` bigint(20) NULL DEFAULT NULL,
  `logintime` bigint(20) NULL DEFAULT NULL,
  `loginip` varchar(50) COLLATE NOCASE NULL DEFAULT NULL,
  `loginfailure` tinyint(3) NOT NULL DEFAULT 0,
  `status` tinyint(1) NOT NULL DEFAULT 0,
  `createtime` datetime NULL DEFAULT NULL,
  `updatetime` datetime NULL DEFAULT NULL,
  `deletetime` datetime NULL DEFAULT NULL
);

