-- ----------------------------
-- Table structure for gf_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `gf_operation_log`;
CREATE TABLE IF NOT EXISTS `gf_operation_log` (
  `id` INTEGER PRIMARY KEY AUTOINCREMENT,
  `business_id` int(11) NOT NULL DEFAULT 0,
  `uid` int(11) NOT NULL DEFAULT 0,
  `method` varchar(10) COLLATE NOCASE NOT NULL DEFAULT '',
  `url` varchar(255) COLLATE NOCASE NOT NULL DEFAULT '',
  `ip` varchar(50) COLLATE NOCASE NOT NULL DEFAULT '',
  `address` varchar(255) COLLATE NOCASE NOT NULL DEFAULT '',
  `des` varchar(100) COLLATE NOCASE NOT NULL DEFAULT '',
  `req_headers` text COLLATE NOCASE NOT NULL DEFAULT '',
  `req_body` text COLLATE NOCASE NOT NULL DEFAULT '',
  `resp_headers` text COLLATE NOCASE NOT NULL DEFAULT '',
  `resp_body` text COLLATE NOCASE NOT NULL DEFAULT '',
  `latency` decimal(10, 4) NOT NULL DEFAULT 0.0000,
  `status` int(2) NOT NULL DEFAULT 0,
  `createtime` datetime NULL DEFAULT NULL
);

